// src/main/services/worldbuilding/characterImpressionService.ts
init_database();
init_CharacterImpressionRecord();
init_WorldEntityRecord();
var MAX_IMPRESSION_TEXT_LENGTH = 12e4;
var MAX_UPDATE_MARKER_LENGTH = 2e4;
var normalizeLongText = (value, maxLength) => String(value ?? "").trim().slice(0, maxLength);
var toPayload4 = (record2) => ({
  characterEntityId: record2.characterEntityId,
  structuredText: record2.structuredText || "",
  updateMarker: record2.updateMarker || "",
  createdAt: record2.createdAt?.toISOString(),
  updatedAt: record2.updatedAt?.toISOString()
});
var CharacterImpressionService = class {
  get entityRepo() {
    return AppDataSource.getRepository(WorldEntityRecord);
  }
  get impressionRepo() {
    return AppDataSource.getRepository(CharacterImpressionRecord);
  }
  async assertCharacterEntity(characterEntityId) {
    const normalizedId = String(characterEntityId || "").trim();
    if (!normalizedId) throw new Error("characterEntityId is required");
    const entity2 = await this.entityRepo.findOneBy({ id: normalizedId });
    if (!entity2) throw new Error(`Character entity not found: ${normalizedId}`);
    if (entity2.type !== "character") {
      throw new Error(`Character impression requires a character entity, received "${entity2.type}"`);
    }
    return entity2;
  }
  async getImpression(characterEntityId) {
    const character = await this.assertCharacterEntity(characterEntityId);
    const record2 = await this.impressionRepo.findOneBy({ characterEntityId: character.id });
    return record2 ? toPayload4(record2) : null;
  }
  async upsertImpression(input) {
    const character = await this.assertCharacterEntity(input.characterEntityId);
    const structuredText = normalizeLongText(input.structuredText, MAX_IMPRESSION_TEXT_LENGTH);
    if (!structuredText) throw new Error("structuredText is required");
    const updateMarker = normalizeLongText(input.updateMarker, MAX_UPDATE_MARKER_LENGTH);
    const current = await this.impressionRepo.findOneBy({ characterEntityId: character.id });
    const record2 = current ?? this.impressionRepo.create({
      characterEntityId: character.id
    });
    record2.structuredText = structuredText;
    record2.updateMarker = updateMarker;
    const saved = await this.impressionRepo.save(record2);
    return toPayload4(saved);
  }
};
var characterImpressionService = new CharacterImpressionService();

// src/main/services/aiservice/ai-utils/tools/character/getCharacterImpression.ts
var getCharacterImpressionTool = defineAgentTool({
  name: "get_character_impression",
  description: "Read the current structured main-agent impression associated with a character.",
  inputSchema: getCharacterImpressionInputSchema,
  outputSchema: getCharacterImpressionOutputSchema,
  metadata: {
    description: {
      purpose: "\u8BFB\u53D6\u4EBA\u7269\u5F53\u524D\u4FDD\u5B58\u7684\u7ED3\u6784\u5316\u4E3B Agent \u5370\u8C61\u3002",
      inputSummary: "\u63D0\u4F9B characterEntityId\u3002",
      outputSummary: "\u8FD4\u56DE found \u548C impression\u3002"
    },
    display: {
      visibility: "visible",
      stage: {
        label: "\u6B63\u5728\u8BFB\u53D6\u4EBA\u7269\u5370\u8C61",
        doneLabel: "\u4EBA\u7269\u5370\u8C61\u8BFB\u53D6\u5B8C\u6210",
        errorLabel: "\u4EBA\u7269\u5370\u8C61\u8BFB\u53D6\u5931\u8D25"
      }
    },
    execution: {
      level: "safe",
      readOnly: true,
      idempotent: true,
      completionSemantics: "definitive"
    },
    retention: { context: "evidence" }
  },
  async execute(input) {
    const impression = await characterImpressionService.getImpression(input.characterEntityId);
    return {
      found: Boolean(impression),
      impression
    };
  },
  successMessage(data, input) {
    return data.found ? `Loaded character impression for ${input.characterEntityId}.` : `No character impression exists for ${input.characterEntityId}.`;
  },
  nextSuggestions(data) {
    if (!data.found) {
      return [
        "Read the character narrative documents and create a first impression if the user requested one."
      ];
    }
    return [
      "Use the saved impression as context; update it only if the user asks or new narrative reading changes it."
    ];
  }
});

