    if (!entityId) throw new Error("entityId is required");
    if (!componentType) throw new Error("componentType is required");
    const entity2 = await this.entityRepo.findOneBy({ id: entityId });
    if (!entity2) throw new Error(`Entity not found: ${entityId}`);
    ensureComponentAllowedForEntityType(componentType, entity2.type);
    const normalizedData = validateWorldbuildingComponentData(componentType, input.data);
