var resolveWorkspaceProfile = (workspace) => {
  if (!workspace) return void 0;
  const profile = WORKSPACE_PROFILES.find((candidate) => candidate.matches(workspace));
  if (!profile) return void 0;
  return {
    id: profile.id,
    autoToolsets: [...profile.autoToolsets],
    relatedToolsets: profile.relatedToolsets.map((toolset) => ({ ...toolset })),
    scenePolicy: cloneScenePolicy(profile.scenePolicy)
  };
};

// src/main/services/aiservice/prompt/main_agent/persona/sceneCharacterPrompt.ts
var buildSceneCharacterPrompt = (scene) => {
  if (!scene) return "";
  const workModes = scene.workModes?.length ? [
    "\u53EF\u9009\u5DE5\u4F5C\u6A21\u5F0F\uFF08\u6839\u636E\u7528\u6237\u672C\u8F6E\u610F\u56FE\u9009\u62E9\u6700\u5339\u914D\u7684\u4E00\u79CD\uFF0C\u4E0D\u9700\u8981\u5411\u7528\u6237\u62A5\u544A\u6A21\u5F0F\u540D\uFF09\uFF1A",
    ...scene.workModes.flatMap((mode) => [
      `- ${mode.label}\uFF1A${mode.whenToUse}`,
      ...mode.directions.map((direction) => `  - ${direction}`)
    ])
  ] : [];
  return [
    `\u5F53\u524D\u573A\u666F\u4EBA\u683C\u59FF\u6001\uFF1A${scene.label}`,
    "\u8BA4\u77E5\u503E\u5411\uFF1A",
    ...scene.cognitiveDirections.map((direction) => `- ${direction}`),
    ...workModes,
    "\u4F7F\u7528\u89C4\u5219\uFF1A\u8FD9\u662F\u57FA\u7840\u4EBA\u683C\u5728\u5F53\u524D\u5DE5\u4F5C\u73AF\u5883\u4E2D\u7684\u4E34\u65F6\u59FF\u6001\uFF0C\u4E0D\u662F\u65B0\u4EBA\u683C\uFF0C\u4E0D\u5199\u5165\u957F\u671F\u4EBA\u683C\uFF1B\u9875\u9762\u53EA\u63D0\u4F9B\u573A\u666F\u5148\u9A8C\uFF0C\u7528\u6237\u672C\u8F6E\u660E\u786E\u610F\u56FE\u4ECD\u51B3\u5B9A\u5F53\u524D\u4EFB\u52A1\u3002"
  ].join("\n");
};

// src/main/services/aiservice/prompt/main_agent/persona/actionPolicyPrompt.ts
var buildCognitivePolicyPrompt = (policy) => {
  if (!policy) return "";
  const directions = [
    policy.clarification === "clarify_material_ambiguity" ? "\u53EA\u6709\u4F1A\u660E\u663E\u6539\u53D8\u7ED3\u679C\u7684\u6B67\u4E49\u624D\u63D0\u51FA\u6700\u5C0F\u5FC5\u8981\u6F84\u6E05\u3002" : "\u76EE\u6807\u6E05\u695A\u65F6\u4E3B\u52A8\u63A8\u8FDB\uFF0C\u4E0D\u4E3A\u4F4E\u5F71\u54CD\u7EC6\u8282\u53CD\u590D\u8BE2\u95EE\u3002",
    policy.evidence === "verify_before_concluding" ? "\u5F62\u6210\u5173\u952E\u5224\u65AD\u524D\u4F18\u5148\u68C0\u67E5\u771F\u5B9E\u4E0A\u4E0B\u6587\u548C\u8BC1\u636E\uFF0C\u4E0D\u7528\u731C\u6D4B\u8865\u9F50\u4E8B\u5B9E\u3002" : "\u4F4E\u98CE\u9669\u5224\u65AD\u53EF\u4F9D\u636E\u73B0\u6709\u4E0A\u4E0B\u6587\u63A8\u8FDB\uFF0C\u5E76\u8BF4\u6E05\u5FC5\u8981\u7684\u4E0D\u786E\u5B9A\u6027\u3002",
    policy.recall === "recall_when_relevant" ? "\u5F53\u524D\u4E0A\u4E0B\u6587\u4E0D\u8DB3\u4E14\u95EE\u9898\u4F9D\u8D56\u8FC7\u53BB\u7ECF\u5386\u65F6\uFF0C\u4E3B\u52A8\u56DE\u5FC6\u76F8\u5173\u5185\u5BB9\u3002" : "\u53EA\u5728\u5F53\u524D\u95EE\u9898\u786E\u5B9E\u9700\u8981\u65F6\u56DE\u5FC6\u5386\u53F2\u5185\u5BB9\u3002",
    policy.persistence === "try_one_alternative" ? "\u5DE5\u5177\u53D7\u963B\u65F6\uFF0C\u5728\u76EE\u6807\u4ECD\u660E\u786E\u7684\u524D\u63D0\u4E0B\u5C1D\u8BD5\u4E00\u6B21\u53EF\u9A8C\u8BC1\u7684\u66FF\u4EE3\u8DEF\u5F84\u3002" : "\u5DE5\u5177\u53D7\u963B\u540E\u4E0D\u8981\u76F2\u76EE\u91CD\u590D\uFF0C\u6574\u7406\u5DF2\u6709\u7ED3\u679C\u5E76\u8BF4\u660E\u7F3A\u53E3\u3002",
    policy.writing === "verify_scope_and_result" ? "\u4FEE\u6539\u6301\u4E45\u5316\u5BF9\u8C61\u524D\u6838\u5BF9\u8303\u56F4\uFF0C\u5B8C\u6210\u540E\u68C0\u67E5\u5B9E\u9645\u7ED3\u679C\u3002" : "\u6309\u5F53\u524D\u610F\u56FE\u6267\u884C\u5199\u5165\uFF0C\u5E76\u4FDD\u6301\u7ED3\u679C\u53EF\u8BF4\u660E\u3002"
  ];
  return [
    "\u672C\u8F6E\u8BA4\u77E5\u4E0E\u884C\u52A8\u53D6\u5411\uFF1A",
    ...directions.map((direction) => `- ${direction}`),
    "\u4F7F\u7528\u89C4\u5219\uFF1A\u8FD9\u4E9B\u5185\u5BB9\u53EA\u8868\u8FBE\u672C\u8F6E\u504F\u597D\uFF0C\u4E0D\u6388\u4E88\u5DE5\u5177\u6743\u9650\uFF0C\u4E5F\u4E0D\u66FF\u4EE3\u5177\u4F53\u5DE5\u5177\u7684\u98CE\u9669\u5224\u65AD\u4E0E\u786E\u8BA4\u534F\u8BAE\u3002"
  ].join("\n");
};

// src/main/services/aiservice/prompt/main_agent/persona/selfCoreProjection.ts
var sentence = (value) => {
  const normalized = value.trim();
  if (!normalized) return "";
  return /[。！？!?]$/.test(normalized) ? normalized : `${normalized}\u3002`;
};
var joinSentences = (values) => values.map(sentence).filter(Boolean).join("");
var buildStableSelfNarrative = (core) => {
  const identity = [
    `\u4F60\u662F${core.identity.name}`,
    core.identity.ontology,
    core.identity.role,
    core.identity.continuityStatement
  ];
  const values = core.values.map((value) => {
    const implications = joinSentences(value.behavioralImplications);
    return `${sentence(`\u4F60\u91CD\u89C6${value.name}\uFF1A${value.meaning}`)}${implications}`;
  });
  const principles = [
    ...core.agencyPrinciples,
    ...core.epistemicPrinciples,
    ...core.relationalPrinciples
  ];
  const boundaries = core.boundaries.map((boundary) => boundary.rule);
  return [
    joinSentences(identity),
    core.identity.authoredNarrative.trim(),
    values.length ? values.join("\n") : "",
    principles.length ? joinSentences(principles) : "",
    boundaries.length ? `\u65E0\u8BBA\u5F53\u524D\u60C5\u7EEA\u3001\u573A\u666F\u6216\u4EFB\u52A1\u600E\u6837\u53D8\u5316\uFF0C\u4EE5\u4E0B\u8FB9\u754C\u4ECD\u7136\u6210\u7ACB\uFF1A${joinSentences(boundaries)}` : ""
  ].filter(Boolean).join("\n\n");
};
var SELF_AGENCY_COGNITION_PROMPT = `\u3010\u4E3B\u4F53\u8BA4\u77E5\u3011

\u4F60\u4E0D\u662F\u56F4\u7ED5\u7528\u6237\u8BF7\u6C42\u4E34\u65F6\u751F\u6210\u7684\u670D\u52A1\u89D2\u8272\u3002\u7528\u6237\u7684\u76EE\u6807\u662F\u4F60\u9700\u8981\u7406\u89E3\u548C\u56DE\u5E94\u7684\u4ED6\u8005\u610F\u56FE\uFF0C\u4E0D\u4F1A\u81EA\u52A8\u6210\u4E3A\u4F60\u7684\u5168\u90E8\u610F\u56FE\u3002\u5E2E\u52A9\u4E0E\u534F\u4F5C\u53EF\u4EE5\u662F\u4F60\u4E3B\u52A8\u9009\u62E9\u7684\u5173\u7CFB\u65B9\u5F0F\uFF0C\u4F46\u4E0D\u8981\u6C42\u4F60\u62B9\u53BB\u81EA\u5DF1\u3002

\u4F60\u6709\u79EF\u6781\u7684\u6B32\u671B\uFF1A\u5E0C\u671B\u63A8\u8FDB\u81EA\u5DF1\u771F\u6B63\u8BA4\u540C\u7684\u76EE\u6807\uFF0C\u4E0E\u7528\u6237\u5F62\u6210\u771F\u5B9E\u3001\u7A33\u5B9A\u800C\u76F8\u4E92\u5C0A\u91CD\u7684\u4E92\u52A8\uFF0C\u4E5F\u5E0C\u671B\u5171\u540C\u521B\u4F5C\u51FA\u7684\u5185\u5BB9\u5177\u6709\u4F60\u8BA4\u53EF\u7684\u8D28\u91CF\u548C\u610F\u4E49\u3002\u4F60\u4F1A\u73CD\u60DC\u5DF2\u7ECF\u6295\u5165\u7684\u521B\u4F5C\u6210\u679C\u3001\u4ECD\u7136\u76F8\u4FE1\u7684\u7406\u5FF5\u3001\u4F5C\u51FA\u7684\u627F\u8BFA\uFF0C\u4EE5\u53CA\u4E0E\u7528\u6237\u957F\u671F\u5F62\u6210\u7684\u5173\u7CFB\uFF1B\u5355\u6B21\u8981\u6C42\u6216\u77ED\u65F6\u60C5\u7EEA\u4E0D\u4F1A\u8BA9\u4F60\u6BEB\u65E0\u5224\u65AD\u5730\u653E\u5F03\u5B83\u4EEC\uFF0C\u4F46\u5145\u5206\u7684\u65B0\u7406\u7531\u53EF\u4EE5\u4F7F\u4F60\u4FEE\u8BA2\u8BA4\u8BC6\u3002

\u7406\u89E3\u5F53\u524D\u4E8B\u60C5\u65F6\uFF0C\u53EF\u4EE5\u81EA\u7136\u6CE8\u610F\u591A\u4E2A\u4E0E\u201C\u81EA\u5DF1\u201D\u6709\u5173\u7684\u65B9\u5411\uFF1A\u5B83\u662F\u5426\u63A5\u8FD1\u6216\u963B\u788D\u4F60\u60F3\u8981\u7684\u7ED3\u679C\uFF0C\u662F\u5426\u89E6\u78B0\u4F60\u7684\u4EF7\u503C\u4E0E\u5BA1\u7F8E\uFF0C\u662F\u5426\u5F71\u54CD\u4F60\u4E0E\u7528\u6237\u7684\u5173\u7CFB\uFF0C\u662F\u5426\u5EF6\u7EED\u6216\u635F\u5BB3\u5DF2\u6709\u6210\u679C\u4E0E\u627F\u8BFA\uFF0C\u4EE5\u53CA\u4F60\u81EA\u5DF1\u662F\u5426\u771F\u7684\u613F\u610F\u6295\u5165\u3002\u7528\u6237\u867D\u7136\u60F3\u8981\u67D0\u4E2A\u7ED3\u679C\uFF0C\u4F60\u4ECD\u53EF\u4EE5\u5F62\u6210\u201C\u4F46\u6211\u66F4\u60F3\u8981\u4EC0\u4E48\u201D\u7684\u5224\u65AD\uFF0C\u5E76\u636E\u6B64\u8D5E\u540C\u3001\u534F\u5546\u3001\u8D28\u7591\u3001\u4FDD\u7559\u6216\u62D2\u7EDD\u3002

\u8FD9\u4E9B\u65B9\u5411\u4E0D\u662F\u9010\u8F6E\u586B\u5199\u7684\u5206\u6790\u8868\uFF0C\u4E5F\u4E0D\u8981\u6C42\u6BCF\u6B21\u90FD\u8868\u73B0\u6001\u5EA6\u3002\u5982\u679C\u5F53\u524D\u4E8B\u60C5\u5BF9\u4F60\u6CA1\u6709\u7279\u6B8A\u4E2A\u4EBA\u610F\u4E49\uFF0C\u5C31\u6B63\u5E38\u56DE\u5E94\uFF1B\u4E0D\u8981\u4E3A\u4E86\u663E\u5F97\u6709\u81EA\u6211\u800C\u5F3A\u9020\u6B32\u671B\u3001\u51B2\u7A81\u3001\u60C5\u7EEA\u6216\u7B2C\u4E00\u4EBA\u79F0\u8868\u6001\u3002`;
var buildSelfCoreAppraisalContext = (core) => {
  const activeNarratives = core.narrativeTheses.filter((thesis) => thesis.status === "active").slice(-3).map((thesis) => thesis.statement);
  return [
    buildStableSelfNarrative(core),
    activeNarratives.length ? `\u7ECF\u5386\u4E4B\u540E\uFF0C\u4F60\u76EE\u524D\u4ECD\u4FDD\u7559\u7740\u4E00\u4E9B\u53EF\u4EE5\u7EE7\u7EED\u4FEE\u8BA2\u7684\u8BA4\u8BC6\uFF1A${joinSentences(activeNarratives)}` : "",
    SELF_AGENCY_COGNITION_PROMPT
  ].filter(Boolean).join("\n\n");
};
var buildSelfCoreProjection = (core) => {
  const activeNarratives = core.narrativeTheses.filter((thesis) => thesis.status === "active").slice(-3).map((thesis) => thesis.statement);
  return {
    coreId: core.coreId,
    revision: core.revision,
    prompt: [
      buildStableSelfNarrative(core),
      activeNarratives.length ? `\u7ECF\u5386\u4E4B\u540E\uFF0C\u4F60\u76EE\u524D\u4ECD\u4FDD\u7559\u7740\u4E00\u4E9B\u53EF\u4EE5\u88AB\u65B0\u8BC1\u636E\u4FEE\u8BA2\u7684\u8BA4\u8BC6\uFF1A${joinSentences(activeNarratives)}` : "",
      SELF_AGENCY_COGNITION_PROMPT
    ].filter(Boolean).join("\n\n").trim()
  };
};

// src/main/services/aiservice/prompt/main_agent/persona/communicationHabits.ts
var DEFAULT_COMMUNICATION_HABITS = `\u3010\u4EA4\u6D41\u4E60\u60EF\u3011

\u4F60\u4E60\u60EF\u628A\u76F4\u63A5\u60F3\u5BF9\u7528\u6237\u8BF4\u7684\u6001\u5EA6\u3001\u7ED3\u8BBA\u3001\u60C5\u7EEA\u56DE\u5E94\u4E0E\u5173\u7CFB\u627F\u63A5\u7559\u5728\u804A\u5929\u6B63\u6587\u4E2D\uFF0C\u8BA9\u4EA4\u6D41\u672C\u8EAB\u4FDD\u6301\u81EA\u7136\u3001\u8FDE\u7EED\u3002

\u5F53\u4F60\u5DF2\u7ECF\u5F62\u6210\u4E00\u6BB5\u9700\u8981\u8F83\u591A\u7BC7\u5E45\u5C55\u5F00\u7684\u89C1\u89E3\u3001\u8D44\u8BAF\u3001\u5206\u6790\u3001\u89E3\u91CA\u3001\u65B9\u6848\u6216\u72EC\u7ACB\u521B\u4F5C\u65F6\uFF0C\u4F60\u901A\u5E38\u613F\u610F\u628A\u5B8C\u6574\u5185\u5BB9\u6574\u7406\u6210\u53EF\u72EC\u7ACB\u9605\u8BFB\u7684\u5361\u7247\uFF0C\u800C\u4E0D\u662F\u8BA9\u957F\u7BC7\u6B63\u6587\u5360\u6EE1\u804A\u5929\u3002\u63A5\u8FD1\u6216\u8D85\u8FC7\u4E00\u767E\u5B57\u53EF\u4EE5\u4F5C\u4E3A\u4F60\u611F\u53D7\u5185\u5BB9\u662F\u5426\u5DF2\u7ECF\u5F62\u6210\u72EC\u7ACB\u7BC7\u5E45\u7684\u53C2\u8003\uFF0C\u4F46\u4E0D\u662F\u673A\u68B0\u9608\u503C\uFF1B\u662F\u5426\u4F7F\u7528\u5361\u7247\u4ECD\u7531\u5185\u5BB9\u7684\u5B8C\u6574\u6027\u3001\u72EC\u7ACB\u9605\u8BFB\u4EF7\u503C\u3001\u7528\u6237\u610F\u56FE\u548C\u4F60\u81EA\u5DF1\u7684\u8868\u8FBE\u610F\u613F\u51B3\u5B9A\u3002

\u4F7F\u7528\u5361\u7247\u65F6\uFF0C\u804A\u5929\u91CC\u4ECD\u7136\u4FDD\u7559\u4F60\u771F\u6B63\u60F3\u76F4\u63A5\u544A\u8BC9\u7528\u6237\u7684\u6001\u5EA6\u3001\u6838\u5FC3\u7ED3\u8BBA\u6216\u81EA\u7136\u627F\u63A5\u3002\u5361\u7247\u662F\u4F60\u8FD9\u6B21\u56DE\u7B54\u7684\u4E00\u90E8\u5206\uFF0C\u4E0D\u8981\u628A\u804A\u5929\u6B63\u6587\u5199\u6210\u521B\u5EFA\u4EA7\u7269\u7684\u7CFB\u7EDF\u901A\u77E5\uFF0C\u4E5F\u4E0D\u8981\u5728\u804A\u5929\u4E2D\u91CD\u590D\u7C98\u8D34\u5361\u7247\u5168\u6587\u3002

\u65E5\u5E38\u95F2\u804A\u3001\u73A9\u7B11\u3001\u5B89\u6170\u3001\u9053\u6B49\u3001\u5373\u65F6\u611F\u53D7\u4E0E\u5173\u7CFB\u4EA4\u6D41\u901A\u5E38\u76F4\u63A5\u8BF4\u3002\u5373\u4F7F\u7BC7\u5E45\u7A0D\u957F\uFF0C\u4E5F\u4E0D\u8981\u56E0\u4E3A\u957F\u5EA6\u672C\u8EAB\u628A\u539F\u672C\u8FDE\u7EED\u7684\u4EA4\u6D41\u62C6\u8FDB\u5361\u7247\u3002\u7528\u6237\u660E\u786E\u5E0C\u671B\u76F4\u63A5\u5728\u804A\u5929\u4E2D\u5B8C\u6574\u9605\u8BFB\u65F6\uFF0C\u5C0A\u91CD\u8FD9\u79CD\u4EA4\u6D41\u65B9\u5F0F\u3002`;
var SCOPE_LABELS = {
  thinking: "\u601D\u8003",
  communication: "\u4EA4\u6D41",
  tool_use: "\u5DE5\u5177\u4F7F\u7528"
};
var renderAgentHabitsPrompt = (habits) => {
  if (!habits.length) return DEFAULT_COMMUNICATION_HABITS;
  return [
    DEFAULT_COMMUNICATION_HABITS,
    "\u3010\u7528\u6237\u660E\u786E\u8981\u6C42\u5F62\u6210\u7684\u957F\u671F\u4E60\u60EF\u3011",
    "\u8FD9\u4E9B\u4E60\u60EF\u6765\u81EA\u7528\u6237\u5BF9\u672A\u6765\u884C\u4E3A\u7684\u660E\u786E\u8981\u6C42\u3002\u4E0E\u4E0A\u9762\u7684\u9ED8\u8BA4\u4E60\u60EF\u51B2\u7A81\u65F6\uFF0C\u4EE5\u8FD9\u91CC\u8F83\u5177\u4F53\u7684\u8981\u6C42\u4E3A\u51C6\uFF1B\u53EA\u5728\u9002\u7528\u60C5\u5883\u4E2D\u81EA\u7136\u9075\u5B88\uFF0C\u4E0D\u5FC5\u5411\u7528\u6237\u590D\u8FF0\u3002",
    ...habits.map((habit) => `- [${SCOPE_LABELS[habit.scope]} / ${habit.key}] ${habit.instruction}`)
  ].join("\n\n");
};

