      source: "taskLifecycle",
      content: `\u5F53\u524D\u6D3B\u8DC3\u4EFB\u52A1:
\u6807\u9898\uFF1A${state.taskLifecycle.activeTask.title}
\u76EE\u6807\uFF1A${state.taskLifecycle.activeTask.goal}
\u72B6\u6001\uFF1A${state.taskLifecycle.activeTask.status}
\u6458\u8981\uFF1A${state.taskLifecycle.activeTask.summary}`
